function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const STOP_WORDS = new Set([
  'and', 'the', 'of', 'for', 'pte', 'ltd', 'limited', 'private', 'singapore', 'sg',
  'medical', 'clinic', 'clinics', 'health', 'healthcare', 'care', 'family', 'group',
  'holdings', 'holding', 'services', 'service', 'centre', 'center'
]);

function tokenise(value) {
  return normalize(value)
    .split(/\s+/)
    .filter((token) => token.length > 1 && !STOP_WORDS.has(token));
}

function overlapCount(a, b) {
  const bSet = new Set(b);
  return a.filter((token) => bSet.has(token)).length;
}

function linkedInSlugTokens(link) {
  try {
    const url = new URL(link);
    const match = url.pathname.match(/\/company\/([^/?#]+)/i);
    if (!match) return [];
    return tokenise(match[1].replace(/-/g, ' '));
  } catch {
    return [];
  }
}

function canonicalLinkedIn(link) {
  try {
    const url = new URL(link);
    const match = url.pathname.match(/(\/company\/[^/?#]+)/i);
    return match ? `${url.origin}${match[1]}/` : link;
  } catch {
    return link;
  }
}

const rawResults = Array.isArray($json.organic)
  ? $json.organic
  : Array.isArray($json.results)
    ? $json.results
    : [];

const results = rawResults.map((result, index) => ({
  position: index + 1,
  link: String(result.link || result.url || '').trim(),
  title: String(result.title || '').trim(),
  snippet: String(result.snippet || result.content || '').trim(),
}));

const homepageName = String($('Parse Parent Company').item.json.company_homepage_name || '').trim();
const parentCompany = String($('Parse Parent Company').item.json.parent_company || '').trim();
const homepageNorm = normalize(homepageName);
const parentNorm = normalize(parentCompany);
const homepageTokens = tokenise(homepageName);
const parentTokens = tokenise(parentCompany);

function scoreResult(result) {
  const link = String(result.link || '').trim();
  if (!/linkedin\.com\/company\//i.test(link)) return null;

  const titleNorm = normalize(result.title || '');
  const snippetNorm = normalize(result.snippet || '');
  const haystack = `${titleNorm} ${snippetNorm}`.trim();
  const slugTokens = linkedInSlugTokens(link);
  const homepageOverlap = overlapCount(homepageTokens, slugTokens);
  const parentOverlap = overlapCount(parentTokens, slugTokens);

  let score = 0;

  if (homepageNorm && titleNorm.includes(homepageNorm)) score += 8;
  else if (homepageNorm && haystack.includes(homepageNorm)) score += 5;

  if (parentNorm && parentNorm !== homepageNorm) {
    if (titleNorm.includes(parentNorm)) score += 7;
    else if (haystack.includes(parentNorm)) score += 4;
  }

  if (homepageOverlap > 0) score += homepageOverlap * 4;
  if (parentNorm && parentNorm !== homepageNorm && parentOverlap > 0) score += parentOverlap * 3;

  if (homepageTokens.length > 0 && homepageOverlap === homepageTokens.length) score += 4;
  if (parentTokens.length > 0 && parentNorm !== homepageNorm && parentOverlap === parentTokens.length) score += 3;

  const hasStrongHomepage = homepageTokens.length > 0 && homepageOverlap >= Math.min(2, homepageTokens.length);
  const hasStrongParent = parentTokens.length > 0 && parentNorm !== homepageNorm && parentOverlap >= Math.min(2, parentTokens.length);
  const phraseMatch = (homepageNorm && haystack.includes(homepageNorm)) || (parentNorm && parentNorm !== homepageNorm && haystack.includes(parentNorm));

  return {
    position: result.position,
    link: canonicalLinkedIn(link),
    score,
    homepageOverlap,
    parentOverlap,
    phraseMatch,
    confident: phraseMatch || hasStrongHomepage || hasStrongParent,
  };
}

const scored = results
  .map(scoreResult)
  .filter(Boolean)
  .sort((a, b) => b.score - a.score || a.position - b.position);

const best = scored[0] || { score: 0, link: '', confident: false };
const accepted = best.confident && best.score >= 6 ? best.link : '';

return [{ json: {
  company_linkedin_url: accepted,
  company_linkedin_score: best.score || 0,
  company_linkedin_candidates: scored.slice(0, 5)
} }];

