}

const GENERIC_TOKENS = new Set(['and','the','pte','ltd','limited','private','singapore','sg','health','healthcare','care','centre','center']);
const LOCATION_TOKENS = new Set(['bishan','aljunied','toa','payoh','bedok','hougang','yishun','woodlands','serangoon','tampines','jurong','bukit','merah','ang','mo','kio','sin','ming','novena','geylang','katong','marine','parade','punggol','sengkang','choa','chu','kang','pasir','ris','queenstown','outram','orchard','clementi','jalan','besar']);
const SOFT_GENERIC_TOKENS = new Set(['medical','clinic','clinics','family','doctor','doctors']);

function tokenize(value) {
  return normalizeText(value)
    .split(/\s+/)
    .filter(Boolean)
    .filter(token => token.length > 1 || /^[0-9]$/.test(token))
    .filter(token => !GENERIC_TOKENS.has(token));
}

function extractDomain(value) {
  const homepage = toHomepageUrl(value);
  if (!homepage) return '';
  return homepage.replace(/^https?:\/\//i, '').replace(/^www\./i, '').replace(/\/+$/, '').toLowerCase();
}

function weightedOverlap(needleTokens, haystackTokens) {
  const haystack = new Set(haystackTokens);
  let score = 0;
  for (const token of needleTokens) {
    if (!haystack.has(token)) continue;
    if (/^[0-9]$/.test(token)) score += 5;
    else if (LOCATION_TOKENS.has(token)) score += 0;
    else if (SOFT_GENERIC_TOKENS.has(token)) score += 1;
    else score += 4;
  }
  return score;
}

function strongBrandTokens(value) {
  return tokenize(value).filter(token => !SOFT_GENERIC_TOKENS.has(token) && !LOCATION_TOKENS.has(token));
}

function scoreResults(results, companyName) {
  const blocked = ['facebook.com','instagram.com','linkedin.com','recordowl.com','healthhub.sg','moh.gov.sg','findhealthclinics.com','wikipedia.org'];
  const companyTokens = tokenize(companyName);
  const brandTokens = strongBrandTokens(companyName);
  const companyNorm = normalizeText(companyName);
  return (Array.isArray(results) ? results : []).map((r, index) => {
    const link = String(r.url || r.link || '').trim();
    if (!link) return null;
    const homepage = toHomepageUrl(link);
    const domain = extractDomain(homepage);
    if (!domain || blocked.some(host => domain === host || domain.endsWith('.' + host))) return null;
    const title = normalizeText(r.title || '');
    const content = normalizeText(r.content || r.snippet || '');
    const haystack = `${title} ${content}`.trim();
    const domainTokens = tokenize(domain.replace(/\.(com|org|net)(\.sg)?$/i, '').replace(/\.sg$/i, '').replace(/[-.]/g, ' '));
    const titleTokens = tokenize(title);
    const haystackTokens = tokenize(haystack);
    const brandOverlap = weightedOverlap(brandTokens, [...domainTokens, ...titleTokens, ...haystackTokens]);
    const totalOverlap = weightedOverlap(companyTokens, [...domainTokens, ...titleTokens, ...haystackTokens]);
    let score = brandOverlap * 3 + totalOverlap;
    if (companyNorm && title.includes(companyNorm)) score += 8;
    else if (companyNorm && haystack.includes(companyNorm)) score += 4;
    if (/\.(com\.sg|org\.sg|sg)$/i.test(domain)) score += 2;
    if (homepage === link || /^https?:\/\/[^/]+\/?$/i.test(link)) score += 1;
    const strong = brandTokens.length > 0 ? brandOverlap >= 4 : totalOverlap >= 5;
    return { homepage, score, index, strong };
  }).filter(Boolean).sort((a, b) => b.score - a.score || a.index - b.index);
}

