const lower = picked.toLowerCase();

if (lower === 'duplicate' || lower === 'none') {
  if (lower === 'none' && topCandidate && topCandidate.strong) {
    // ignore weak LLM none if deterministic candidate is clearly better
  } else {
    return [{ json: { best_url: lower } }];
  }
}

const tokens = picked.split(/\s+/).map(t => t.trim()).filter(Boolean);
const stripEdge = (s) => String(s || '').replace(/^[`'"<({\[]+/, '').replace(/[`'">)}\],.]+$/, '');

let normalized = '';
const urlToken = tokens.find(t => /^https?:\/\//i.test(stripEdge(t)));
if (urlToken) {
  normalized = stripEdge(urlToken);
} else {
  const domainToken = tokens.find(t => {
    const v = stripEdge(t).replace(/^https?:\/\//i, '').replace(/^www\./i, '');
    return v.includes('.') && /^[a-z0-9.-]+(?:\/[^\s]*)?$/i.test(v);
  });
  if (domainToken) {
    normalized = 'https://' + stripEdge(domainToken).replace(/^https?:\/\//i, '');
  }
}

const normalizedHomepage = normalized ? toHomepageUrl(normalized) : '';
const normalizedDomain = normalizedHomepage ? extractDomain(normalizedHomepage) : '';
const chosenScore = normalizedDomain
  ? (scoredResults.find(candidate => extractDomain(candidate.homepage) === normalizedDomain) || null)
  : null;

if (!normalizedHomepage || !chosenScore || !chosenScore.strong) {
  normalized = topCandidate && topCandidate.strong ? topCandidate.homepage : '';
} else {
  normalized = normalizedHomepage;
}

if (!normalized) {
  return [{ json: { best_url: 'none' } }];
}

const homepageUrl = toHomepageUrl(normalized);
