const pickedHomepage = extractDomain(homepageUrl);

const isDuplicate = allUrls.some(function(u) {
  return extractDomain(u) === pickedHomepage;
});

if (isDuplicate) {
  return [{ json: { best_url: 'duplicate' } }];
}

return [{ json: { best_url: homepageUrl } }];

